// Generated by OrchestKit Claude Plugin
// Created: 2026-09-25

/**
 * mask() must stay linear on long non-whitespace runs. A prefix hit extends
 * to the end of its run; resuming the search one character later rescanned
 * the same run for every repeated prefix, so one long line could hold the
 * session for seconds in a single synchronous call no deadline can interrupt.
 */

import { describe, test, expect } from "vitest";
import { setFlagsFromString } from "node:v8";
import { runInNewContext } from "node:vm";
import { buildTable, mask, DEFAULT_PATTERNS } from "../src/mask.js";

// Node documents changing V8 flags after startup as unsupported; it is used here so no vitest
// config flag is needed (the diff stays test-only). The "gc() is exposed" test trips if Node breaks it.
setFlagsFromString("--expose-gc");
const gc = runInNewContext("gc") as (() => void) | undefined;

const table = buildTable([], {}, DEFAULT_PATTERNS, { entropy: true });

function timed(text: string): { ms: number; out: string } {
  const t0 = performance.now();
  const out = mask(text, table).text;
  return { ms: performance.now() - t0, out };
}

describe("mask() stays fast on long runs", () => {
  test("a 100k-character run of a repeated key prefix scales linearly against a tenth of it and is masked", () => {
    const run = "AK" + "IA";
    const text = run.repeat(25_000);
    expect(text.length).toBe(100_000);
    expectLinearAgainstTenth(text);
    expect(timed(text).out).not.toContain(run);
  });

  test("a minified line full of a prefix inside ordinary words scales linearly against a tenth of it", () => {
    // "props_" contains the service-account prefix "ops_".
    const text = "{props_a:1,props_b:2,props_c:3}".repeat(3_300);
    expect(text.length).toBeGreaterThan(100_000);
    expectLinearAgainstTenth(text);
  });

  test("a repeated named value is still found everywhere it occurs", () => {
    const named = buildTable(["X_TOKEN"], { X_TOKEN: "veiltest-synthetic-value-42" }, DEFAULT_PATTERNS, { entropy: true });
    const text = "a veiltest-synthetic-value-42 b veiltest-synthetic-value-42 c";
    const out = mask(text, named).text;
    expect(out).not.toContain("veiltest-synthetic-value-42");
    expect(out.startsWith("a ")).toBe(true);
    expect(out).toContain(" b ");
    expect(out.endsWith(" c")).toBe(true);
  });

  // The two million-character cases check SCALING, not a wall-clock bound
  // tuned to one machine: a CI runner measured 206 ms on a case this machine
  // runs in about 31 ms. Linear work grows about 10x from 100k to 1M; the
  // old quadratic code grew about 100x (and took 5 to 40 s at 1M). The 1 s
  // ceiling is a backstop that still fails any quadratic regression.
  //
  // The ratio limit sits halfway between linear and quadratic on a log scale,
  // sqrt(10 * 100) = 31.6x, so either side can drift about 3x before a linear
  // run fails or a quadratic one passes. A 20x limit left only 2x: the 100k
  // side takes about 4 ms on a shared runner, and nightly run 40154035027
  // failed a linear run at 21.3x (84.69 ms against 3.97 ms). A fit over three
  // log-spaced sizes would not help: its least-squares slope depends on the
  // two end points only, so it is this same ratio test at more cost.
  //
  // Each size takes the MINIMUM of 7 runs, with a forced GC before each run.
  // Host load and GC only ever add time, so the minimum is the cleanest
  // reading; a median of 5 still measured 34x on a linear run at load 59.
  // The spaced case builds about 200k spans per call at 1M, and garbage left
  // by earlier runs was collected inside the measured one (GC was 257 ms of
  // a 333 ms median). The forced GC clears it first; GC caused by the run
  // itself still counts, so a quadratic stand-in still fails.
  const LINEAR_RATIO_LIMIT = Math.sqrt(10 * 100);
  const FLOOR_MS = 20;
  const RUNS = 7;

  type Run = (text: string) => void;
  const maskRun: Run = (text) => {
    mask(text, table);
  };
  const minMs = (run: Run, text: string): number => {
    run(text); // warm-up, not counted
    let best = Infinity;
    for (let i = 0; i < RUNS; i++) {
      gc?.();
      const t0 = performance.now();
      run(text);
      best = Math.min(best, performance.now() - t0);
    }
    return best;
  };
  const scaling = (unit: string, run: Run = maskRun): { small: number; large: number } => {
    const small = unit.repeat(Math.ceil(100_000 / unit.length));
    const large = unit.repeat(Math.ceil(1_000_000 / unit.length));
    return { small: minMs(run, small), large: minMs(run, large) };
  };

  test("gc() is exposed, so the scaling cases measure without earlier garbage", () => {
    // Without it the forced GC is skipped and the spaced case goes back to flaking.
    expect(typeof gc).toBe("function");
  });
  const scalesLinearly = ({ small, large }: { small: number; large: number }): boolean =>
    large < Math.max(LINEAR_RATIO_LIMIT * small, FLOOR_MS);

  // #4899: the two 100k cases above used one wall-clock reading against a
  // fixed 200 ms, and a loaded host failed linear code that way (310 ms at
  // load1 about 52, 2026-10-25). They now take the same minimum-of-7 ratio as
  // the scaling cases, against the first tenth of the same input, with the
  // 1 s backstop so a quadratic regression still fails if both sides slow
  // down together. Defined here, used by tests that run after this body.
  const expectLinearAgainstTenth = (text: string): void => {
    const times = {
      small: minMs(maskRun, text.slice(0, Math.ceil(text.length / 10))),
      large: minMs(maskRun, text),
    };
    expect(times.large).toBeLessThan(1000);
    expect(scalesLinearly(times), JSON.stringify(times)).toBe(true);
  };

  test("BEGIN markers with no END scale linearly (10x input, under 31.6x time) and stay under 1 s at 1M", () => {
    const times = scaling("-----" + "BEGIN ");
    expect(times.large).toBeLessThan(1000);
    expect(scalesLinearly(times), JSON.stringify(times)).toBe(true);
  });

  test("short spaced prefix tokens scale linearly (10x input, under 31.6x time), stay under 1 s, and are masked", () => {
    const unit = "AK" + "IA ";
    const times = scaling(unit);
    expect(times.large).toBeLessThan(1000);
    expect(scalesLinearly(times), JSON.stringify(times)).toBe(true);
    expect(timed(unit.repeat(200_000)).out).not.toContain("AK" + "IA");
  });

  test("the scaling check accepts the linear run the 20x limit failed on 2026-10-25", () => {
    expect(scalesLinearly({ small: 3.97, large: 84.69 })).toBe(true);
  });

  // The controls below prove scalesLinearly() itself: it must reject quadratic growth and
  // accept linear growth. They count steps instead of timing them. The old control timed
  // a quadratic loop, and on a slow GitHub runner the 100k side cost about 3x more per
  // step than the 1M side, so it measured {small: 2.88, large: 84.04} ms, a 29.2x ratio,
  // which this check (correctly) reads as linear, and the control failed (PR #5236, Mods
  // job 132734827017). It did not reproduce locally (0 of 20 rounds under 31.6x), so a
  // wall-clock control is a coin toss on a bad runner. The three timed tests above still
  // measure the real mask() code.
  const MS_PER_MILLION_STEPS = 1;
  const modelled = (steps: (len: number) => number) => ({
    small: (steps(100_000) / 1e6) * MS_PER_MILLION_STEPS,
    large: (steps(1_000_000) / 1e6) * MS_PER_MILLION_STEPS,
  });

  test("the scaling check fails a quadratic implementation (counted steps, not wall time)", () => {
    // Stand-in for the old rescan: (n / 100)^2 steps, so 1M chars costs 100x what 100k does.
    const times = modelled((len) => Math.floor(len / 100) ** 2);
    expect(times.large / times.small).toBe(100);
    expect(times.large, "quadratic model must clear the floor").toBeGreaterThan(FLOOR_MS);
    expect(scalesLinearly(times), JSON.stringify(times)).toBe(false);
  });

  test("the scaling check passes a linear implementation (counted steps, not wall time)", () => {
    // Same units, linear work: 1M chars costs 10x what 100k does.
    const times = modelled((len) => len * 300);
    expect(times.large / times.small).toBe(10);
    expect(times.large).toBeGreaterThan(FLOOR_MS);
    expect(scalesLinearly(times), JSON.stringify(times)).toBe(true);
  });
});

